// Package postgres implements page.Repository against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"slices"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/cowork/internal/page"
	"github.com/garamsh/garam/cowork/internal/page/postgres/db"
	"github.com/garamsh/garam/lib/errorx"
	"github.com/garamsh/garam/lib/grn"
)

// foreignKeyViolation is the SQL state of a reference to a row that
// does not exist: here, a parent page.
const foreignKeyViolation = "23503"

// Repository implements page.Repository against PostgreSQL.
type Repository struct {
	pool *pgxpool.Pool
	now  func() time.Time
}

var _ page.Repository = (*Repository)(nil)

// New answers a repository over pool.
func New(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool, now: time.Now}
}

// translate turns a driver error into the domain's: a missing row or a
// missing parent is page.ErrPageNotFound, anything else is wrapped as
// unavailable.
func translate(err error, op string) error {
	var pgErr *pgconn.PgError
	switch {
	case err == nil:
		return nil
	case errors.Is(err, pgx.ErrNoRows):
		return page.ErrPageNotFound
	case errors.As(err, &pgErr) && pgErr.Code == foreignKeyViolation:
		return page.ErrPageNotFound
	case errorx.KindOf(err) != errorx.KindUnknown:
		return err
	}
	return errorx.Wrap(err, "pages: "+op, errorx.KindUnavailable)
}

func parentText(parent string) pgtype.Text {
	return pgtype.Text{String: parent, Valid: parent != ""}
}

func fromRow(r db.Page) (page.Page, error) {
	creator, err := grn.Parse(r.CreatedBy)
	if err != nil {
		return page.Page{}, errorx.Wrap(err, "pages: stored creator", errorx.KindDataLoss)
	}
	return page.Page{
		ID:        r.ID,
		Org:       r.Org,
		Parent:    r.ParentID.String,
		Title:     r.Title,
		Position:  int(r.Position),
		CreatedBy: creator,
		CreatedAt: r.CreatedAt.Time,
		UpdatedAt: r.UpdatedAt.Time,
	}, nil
}

// inTree runs fn in a transaction holding the organization's tree
// lock.
func (r *Repository) inTree(ctx context.Context, org string, fn func(q *db.Queries) error) error {
	return pgx.BeginFunc(ctx, r.pool, func(tx pgx.Tx) error {
		q := db.New(tx)
		if err := q.LockTree(ctx, org); err != nil {
			return err
		}
		return fn(q)
	})
}

// List implements page.Repository.
func (r *Repository) List(ctx context.Context, org string) ([]page.Page, error) {
	rows, err := db.New(r.pool).ListPages(ctx, org)
	if err != nil {
		return nil, translate(err, "list")
	}
	out := make([]page.Page, 0, len(rows))
	for _, row := range rows {
		p, err := fromRow(row)
		if err != nil {
			return nil, err
		}
		out = append(out, p)
	}
	return out, nil
}

// Get implements page.Repository.
func (r *Repository) Get(ctx context.Context, org, id string) (page.Page, error) {
	row, err := db.New(r.pool).GetPage(ctx, db.GetPageParams{Org: org, ID: id})
	if err != nil {
		return page.Page{}, translate(err, "get")
	}
	return fromRow(row)
}

// Create implements page.Repository.
func (r *Repository) Create(ctx context.Context, p page.Page) (page.Page, error) {
	var out page.Page
	err := r.inTree(ctx, p.Org, func(q *db.Queries) error {
		n, err := q.CountSiblings(ctx, db.CountSiblingsParams{Org: p.Org, ParentID: parentText(p.Parent)})
		if err != nil {
			return err
		}
		row, err := q.InsertPage(ctx, db.InsertPageParams{
			Org:       p.Org,
			ID:        p.ID,
			ParentID:  parentText(p.Parent),
			Title:     p.Title,
			Position:  int32(n),
			CreatedBy: p.CreatedBy.String(),
			CreatedAt: pgtype.Timestamptz{Time: r.now(), Valid: true},
		})
		if err != nil {
			return err
		}
		out, err = fromRow(row)
		return err
	})
	return out, translate(err, "create")
}

// renumber writes positions 0, 1, 2 ... to ids in order.
func renumber(ctx context.Context, q *db.Queries, org string, ids []string) error {
	for i, id := range ids {
		if err := q.SetPosition(ctx, db.SetPositionParams{Org: org, ID: id, Position: int32(i)}); err != nil {
			return err
		}
	}
	return nil
}

// Update implements page.Repository.
func (r *Repository) Update(ctx context.Context, org, id string, in page.UpdateInput) (page.Page, error) {
	var out page.Page
	err := r.inTree(ctx, org, func(q *db.Queries) error {
		row, err := q.GetPage(ctx, db.GetPageParams{Org: org, ID: id})
		if err != nil {
			return err
		}
		title, parent, position := row.Title, row.ParentID.String, int(row.Position)
		if in.Title != nil {
			title = *in.Title
		}
		if in.Parent != nil && *in.Parent != "" {
			above, err := q.AncestorIDs(ctx, db.AncestorIDsParams{Org: org, ID: *in.Parent})
			if err != nil {
				return err
			}
			if len(above) == 0 {
				return page.ErrPageNotFound
			}
			if slices.Contains(above, id) {
				return page.ErrPageCycle
			}
		}
		if in.Parent != nil || in.Position != nil {
			left, err := q.ListSiblingIDs(ctx, db.ListSiblingIDsParams{Org: org, ParentID: row.ParentID})
			if err != nil {
				return err
			}
			left = slices.DeleteFunc(left, func(s string) bool { return s == id })
			if err := renumber(ctx, q, org, left); err != nil {
				return err
			}
			if in.Parent != nil {
				parent = *in.Parent
			}
			joined, err := q.ListSiblingIDs(ctx, db.ListSiblingIDsParams{Org: org, ParentID: parentText(parent)})
			if err != nil {
				return err
			}
			joined = slices.DeleteFunc(joined, func(s string) bool { return s == id })
			position = len(joined)
			if in.Position != nil {
				position = min(*in.Position, len(joined))
			}
			joined = slices.Insert(joined, position, id)
			if err := renumber(ctx, q, org, joined); err != nil {
				return err
			}
		}
		updated, err := q.UpdatePage(ctx, db.UpdatePageParams{
			Org: org, ID: id, Title: title, ParentID: parentText(parent), Position: int32(position),
			UpdatedAt: pgtype.Timestamptz{Time: r.now(), Valid: true},
		})
		if err != nil {
			return err
		}
		out, err = fromRow(updated)
		return err
	})
	return out, translate(err, "update")
}

// Delete implements page.Repository. The pages beneath go by the
// foreign key's cascade, and so does every page's content.
func (r *Repository) Delete(ctx context.Context, org, id string) error {
	err := r.inTree(ctx, org, func(q *db.Queries) error {
		row, err := q.GetPage(ctx, db.GetPageParams{Org: org, ID: id})
		if err != nil {
			return err
		}
		if _, err := q.DeletePage(ctx, db.DeletePageParams{Org: org, ID: id}); err != nil {
			return err
		}
		left, err := q.ListSiblingIDs(ctx, db.ListSiblingIDsParams{Org: org, ParentID: row.ParentID})
		if err != nil {
			return err
		}
		return renumber(ctx, q, org, left)
	})
	return translate(err, "delete")
}
